document.addEventListener('click',e=>{if(e.target.matches('[data-reveal-btn]')){const box=e.target.parentElement.querySelector('[data-reveal]');const good=(box.dataset.correct||'').split(',').filter(Boolean).map(Number);box.querySelectorAll('.answer').forEach(a=>{if(good.includes(Number(a.dataset.index)))a.classList.add('correct')});}});document.querySelectorAll('[data-filter]').forEach(input=>input.addEventListener('input',()=>{const list=document.querySelector('[data-list="'+input.dataset.filter+'"]');if(!list)return;[...list.children].forEach(el=>{el.style.display=el.textContent.toLowerCase().includes(input.value.toLowerCase())?'':'none'})}));